from lib import *
S = SS('p10')
steps = [
    step("HTTP/2 是在 TLS 握手里协商出来的(ALPN)。同一个 nginx:客户端声明 h2 和 http/1.1,协商结果是 h2;只声明 http/1.1,结果是 http/1.1(都是 TLS 1.3)。nginx 访问日志的协议列也印证了:requests 的请求是 HTTP/1.1,curl_cffi 指定 http_version='v2' 的请求是 HTTP/2.0。requests 本身只会说 HTTP/1.1,要抓 HTTP/2 就得换客户端。", t=tl(S(1)), done=lidx(S(1), '协商结果 h2', 'nginx 访问日志'), mark=lidx(S(1), '协商结果 http/1.1'), kv=KV([['声明 h2', '协商出 h2'], ['只声明 http/1.1', '协商出 http/1.1'], ['requests', '只说 HTTP/1.1']], ['声明 h2'])),
    step("50 个请求、服务器每个停 0.1 秒,用同一个客户端库(curl_cffi)的两种协议,并发数对齐。并发 1:HTTP/1.1 和 HTTP/2 都是 1 条连接、约 5.2 秒,没有区别;并发 6:HTTP/1.1 用 6 条连接 948 ms;并发 50:HTTP/1.1 用 50 条连接 121 ms,HTTP/2 只用 1 条连接 111 ms;HTTP/2 并发 10 是 526 ms(1 条连接)。总耗时由并发数决定;HTTP/2 的好处是 50 个并发只占 1 条连接,速度并没有明显更快。", t=tl(S(2)), done=lidx(S(2), 'HTTP/2       50', 'HTTP/2       10'), mark=lidx(S(2), 'HTTP/1.1     50', 'HTTP/1.1      6'), b=bars([['HTTP/1.1 并发 50:连接数', 50, '50'], ['HTTP/2 并发 50:连接数', 1, '1'], ['HTTP/1.1 并发 50:耗时 ms', 121, '121'], ['HTTP/2 并发 50:耗时 ms', 111, '111']], 125, mark=[0], done=[1]), kv=KV([['并发 50', 'HTTP/1.1 50 条连接,HTTP/2 1 条'], ['耗时', '121 ms 对 111 ms,差别很小'], ['决定耗时的', '并发数,不是协议']], ['决定耗时的'])),
    step("服务器不延迟、600 个请求,这时建立连接本身的开销显出来:并发 50 时,HTTP/1.1 用了 122 条连接(每条仅十几个请求;各次运行在 86 到 122 条之间波动,libcurl 会关掉再重开连接)、总耗时 131 ms;HTTP/2 一条连接承载了全部 600 个请求,94 ms。并发 6:HTTP/1.1 41 条连接 146 ms,HTTP/2 1 条连接 119 ms。本机回环没有网络延迟,差距主要是建连接和握手的 CPU 开销。", t=tl(S(3)), done=lidx(S(3), 'HTTP/2   并发 50', 'HTTP/2   并发  6'), mark=lidx(S(3), 'HTTP/1.1 并发 50', 'HTTP/1.1 并发  6'), b=bars([['HTTP/1.1 并发 50 (ms)', 131, '131'], ['HTTP/2 并发 50 (ms)', 94, '94'], ['HTTP/1.1 并发 6 (ms)', 146, '146'], ['HTTP/2 并发 6 (ms)', 119, '119']], 150, mark=[0, 2], done=[1, 3]), kv=KV([['HTTP/2', '1 条连接承载 600 个请求'], ['HTTP/1.1 并发 50', '122 条连接(86–122 波动)'], ['无延迟时', 'HTTP/2 94 ms 对 131 ms']], ['HTTP/2'])),
    step("服务器通过 http2_max_concurrent_streams 告诉客户端同一条连接上最多并发多少个流。设成 128 时 50 个并发请求只用 1 条连接,111 ms;设成 10 时,curl_cffi 自动开了 5 条连接、每条 10 个请求,114 ms;设成 2 时开了 25 条连接、每条 2 个,125 ms。也就是说客户端遵守服务器的流上限,上限小时 HTTP/2 就退化成多条连接。另外,在另一次运行里 streams 设为 2 和 1 时我遇到过 curl_cffi 报 Connection died,没有查原因。", t=tl(S(4)), done=lidx(S(4), 'max_concurrent_streams=128'), mark=lidx(S(4), 'max_concurrent_streams=10', 'max_concurrent_streams=2'), b=bars([['streams=128:连接数', 1, '1'], ['streams=10:连接数', 5, '5'], ['streams=2:连接数', 25, '25']], 25, done=[0], mark=[1, 2]), kv=KV([['streams=128', '1 条连接'], ['streams=10', '5 条连接'], ['streams=2', '25 条连接']], ['streams=10'])),
    step("队头阻塞:第 1 个请求很慢(0.5 秒),后面 20 个很快(0.02 秒)。HTTP/1.1 一条连接串行:慢请求 507 ms 完成,20 个快请求要等它,最早 532 ms、最晚 985 ms 才完成;HTTP/1.1 六条连接:快请求在 23–101 ms 完成;HTTP/2 一条连接:快请求在 26–28 ms 就全部完成,慢请求 507 ms。HTTP/2 在同一条连接上让快请求绕开了慢请求。", t=tl(S(5)), done=lidx(S(5), 'HTTP/2 一条连接'), mark=lidx(S(5), 'HTTP/1.1 一条连接(串行)'), b=bars([['HTTP/1.1 一条连接:快请求最晚完成 ms', 985, '985'], ['HTTP/1.1 六条连接:快请求最晚完成 ms', 101, '101'], ['HTTP/2 一条连接:快请求最晚完成 ms', 28, '28']], 1000, mark=[0], done=[2]), kv=KV([['HTTP/1.1 一条连接', '快请求排在慢请求后面'], ['HTTP/1.1 六条连接', '分散到多条连接'], ['HTTP/2', '同一条连接上并行']], ['HTTP/2'])),
]
A = mkartp('p10', 10, '爬虫,HTTP/2,多路复用,curl_cffi,nginx,ALPN,并发,真实验证,动画演示',
    '用本机 nginx(HTTP/2)和 curl_cffi 把 HTTP/1.1 与 HTTP/2 的并发对齐后比较:50 个并发请求 HTTP/1.1 用 50 条连接 121 ms,HTTP/2 用 1 条连接 111 ms;无延迟的 600 个请求 131 ms 对 94 ms;服务器流上限为 10 时客户端自动开 5 条连接;一条连接上快请求不再排在慢请求后面。',
    '“上 HTTP/2 就更快”是爬虫圈里常见的说法。这篇在本机用 nginx 起一个真实的 HTTP/2 服务,把客户端库、并发数都对齐之后,看 HTTP/2 到底换来了什么:连接数、耗时、服务器的流上限,以及队头阻塞。',
    [('1 对 50', '并发 50 个请求时,HTTP/2 与 HTTP/1.1 用到的连接数'), ('111 对 121 ms', '同样并发 50、服务器每个请求停 0.1 秒:HTTP/2 和 HTTP/1.1 的总耗时,几乎一样'), ('28 对 985 ms', '慢请求在前时,20 个快请求最晚完成的时间:HTTP/2 一条连接对 HTTP/1.1 一条连接')],
    [('协商出 HTTP/2', '<p>HTTP/2 通过 TLS 握手里的 ALPN 协商。客户端声明 <code>h2</code> 且服务器支持就用 HTTP/2,只声明 <code>http/1.1</code> 就是 HTTP/1.1。<code>requests</code> 只会说 HTTP/1.1,所以这篇改用 <code>curl_cffi</code>。</p>'),
     ('总耗时由并发数决定', '<p>服务器每个请求停 0.1 秒时,50 个请求的总耗时取决于同时飞行多少个:并发 1 约 5.2 秒、并发 6 约 0.95 秒、并发 50 约 0.12 秒。HTTP/2 在并发 50 时只用一条连接,耗时 111 ms,与 HTTP/1.1 开 50 条连接的 121 ms 差不多。注意 <code>curl_cffi</code> 的默认并发上限(<code>max_clients</code>)是 10,不改的话 50 个请求要分 5 批,和 HTTP/2 本身无关。</p>'),
     ('连接开销', '<p>服务器不延迟时,请求本身几乎不花时间,建立连接和握手的开销就明显了:600 个请求并发 50,HTTP/1.1 开了上百条连接、131 ms,HTTP/2 一条连接、94 ms。这是本机回环的结果,没有真实网络的往返时间;真实网络上每条新连接还要多付往返,差距只会更大(我没有测)。</p>'),
     ('服务器的流上限', '<p>服务器声明的最大并发流数限制了一条连接能同时承载多少请求。上限 128 时 50 个请求用 1 条连接;上限 10 时客户端自动开了 5 条;上限 2 时开了 25 条。这说明“HTTP/2 一条连接搞定一切”取决于服务器配置。流上限设得很小时,我遇到过一次 curl_cffi 报 Connection died,没有查原因。</p>'),
     ('队头阻塞', '<p>HTTP/1.1 一条连接上请求按顺序处理,慢请求排在前面,后面的快请求都要等(最晚 985 ms 才完成)。HTTP/2 在同一条连接上并行处理,快请求在 28 ms 内全部完成。开多条 HTTP/1.1 连接也能缓解(101 ms),代价是更多的连接。这里的慢请求只是服务器端的延迟;TCP 层的队头阻塞(丢包时影响整条连接)本机回环里测不出来。</p>')],
    steps,
    [ENV_P + '。HTTP/2 服务端是本机 nginx 1.31.6(只监听 127.0.0.1,自签名证书,独立 prefix),反向代理到我的 Python 后端(后端按查询串 d 停顿);客户端是 curl_cffi 0.15.0(libcurl,开启 PIPEWAIT 让并发请求等待复用同一条连接),HTTP/1.1 与 HTTP/2 都用它,max_clients 对齐并发数;连接数与协议取自 nginx 访问日志的 $connection 和 $server_protocol;每个配置跑 3 次(无延迟的 600 请求跑 5 次)取总耗时中位数,并发 1 的只跑了 1 次',
     '没有验证:真实网络延迟与丢包下的表现(TCP 层的队头阻塞);HTTP/3;其它支持 HTTP/2 的客户端(httpx 等没有安装);不开 PIPEWAIT 时的连接数(默认会因为并发建连而开出多条连接);流上限为 1 或 2 时偶发的 Connection died 的原因;aiohttp(只支持 HTTP/1.1)的对比;服务端是 nginx 以外的实现时的行为'],
    'HTTP/2 多路复用')
